#!/usr/bin/env bash
# scripts/capabilities.sh — generate the capability catalog from openspec/specs/.
#
# The catalog enumerates every LIVE capability (a directory under
# `openspec/specs/` that contains a `spec.md`) with a relative link to
# its spec. It backs the README's capability navigation and is
# regenerated by the `docs` gate: if the checked-in
# `docs/CAPABILITIES.md` drifts from the live spec set, `make docs`
# fails. Never edit the generated catalog by hand.
#
# The **Shipped nav** column is a cross-check against the shipped web
# navigation registry (`crates/openpanel-web/src/capability_registry.rs`),
# not a second registry: `yes` means some registry entry exposes a
# capability whose identifier equals the spec folder name. The registry
# names runtime capabilities and routes, so a mismatch with a spec
# folder name is expected and is reconciled explicitly below the table.
#
# The output is deterministic (no timestamps) so regeneration is
# idempotent.
#
# Usage:
#   scripts/capabilities.sh                        # catalog to stdout
#   scripts/capabilities.sh > docs/CAPABILITIES.md # regenerate the page
#
# Environment overrides (self-test fixtures):
#   OPENPANEL_CAPABILITIES_SPECS     — specs dir (default <repo>/openspec/specs)
#   OPENPANEL_CAPABILITIES_REGISTRY  — registry file (default <repo>/crates/.../capability_registry.rs)
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SPECS_DIR="${OPENPANEL_CAPABILITIES_SPECS:-${REPO_ROOT}/openspec/specs}"
REGISTRY="${OPENPANEL_CAPABILITIES_REGISTRY:-${REPO_ROOT}/crates/openpanel-web/src/capability_registry.rs}"

if [ ! -d "${SPECS_DIR}" ]; then
    echo "capabilities.sh: specs dir not found: ${SPECS_DIR}" >&2
    exit 1
fi

# Capability identifiers referenced by the shipped navigation registry.
reg_caps=""
reg_entry_count=0
if [ -f "${REGISTRY}" ]; then
    reg_caps="$(grep -oE 'capability: "[^"]+"' "${REGISTRY}" \
        | sed -E 's/capability: "([^"]+)"/\1/' | sort -u || true)"
    reg_entry_count="$(grep -cE '^[[:space:]]*RouteMeta \{$' "${REGISTRY}" || true)"
fi
reg_cap_count="$(printf '%s\n' "${reg_caps}" | grep -c . || true)"

live_caps="$(ls "${SPECS_DIR}" | sort)"

count=0
{
    echo "# Capability catalog"
    echo
    echo "<!-- Generated by scripts/capabilities.sh. Do not edit by hand. -->"
    echo
    echo "Every live capability under \`openspec/specs/\` with a link to its"
    echo "spec. Regenerate with:"
    echo
    echo '```sh'
    echo "scripts/capabilities.sh > docs/CAPABILITIES.md"
    echo '```'
    echo
    echo "The \`docs\` leg of \`make check\` fails when this file drifts from the"
    echo "live spec set, so the capability surface stays navigable instead of"
    echo "being asserted in prose."
    echo
    echo "The **Shipped nav** column cross-checks the shipped web navigation"
    echo "registry (\`crates/openpanel-web/src/capability_registry.rs\`); it is a"
    echo "reference, not a second source of truth."
    echo
    echo "| Capability | Spec | Shipped nav |"
    echo "| --- | --- | --- |"
    for cap in ${live_caps}; do
        [ -f "${SPECS_DIR}/${cap}/spec.md" ] || continue
        nav=""
        if printf '%s\n' "${reg_caps}" | grep -qxF "${cap}"; then
            nav="yes"
        fi
        printf '| `%s` | [spec](../openspec/specs/%s/spec.md) | %s |\n' \
            "${cap}" "${cap}" "${nav}"
        count=$((count + 1))
    done
    echo
    echo "**Total live capabilities: ${count}.**"
    echo
    echo "## Navigation registry reconciliation"
    echo
    echo "The shipped navigation registry exposes ${reg_entry_count} entries"
    echo "across ${reg_cap_count} capability identifiers. Identifiers without a"
    echo "live capability folder of the same name are expected: the registry"
    echo "names runtime capabilities and routes, while the catalog names spec"
    echo "folders."
    echo
    echo "| Registry capability | Live spec |"
    echo "| --- | --- |"
    for cap in ${reg_caps}; do
        if [ -f "${SPECS_DIR}/${cap}/spec.md" ]; then
            printf '| `%s` | [spec](../openspec/specs/%s/spec.md) |\n' "${cap}" "${cap}"
        else
            printf '| `%s` | — (no spec folder of this name) |\n' "${cap}"
        fi
    done
} # end catalog

if [ "${count}" -eq 0 ]; then
    echo "capabilities.sh: no live capabilities found under ${SPECS_DIR}" >&2
    exit 1
fi
